"""Build the portable manifest, layered scene and local review pages.
Requires Python 3 + Pillow. Reads PNGs for metadata only; never edits bitmap pixels.
Run from any directory: python3 /path/to/02_可编辑源文件/build-delivery.py
"""
from pathlib import Path
import json, hashlib, base64, html
from PIL import Image

ROOT = Path(__file__).resolve().parent.parent
def read(p): return json.loads((ROOT / p).read_text())
def write(p, s):
    f = ROOT / p
    f.parent.mkdir(parents=True, exist_ok=True)
    f.write_text(s, encoding='utf-8')
def dump(p, data): write(p, json.dumps(data, ensure_ascii=False, indent=2)+'\n')
def digest(p): return hashlib.sha256(p.read_bytes()).hexdigest()
def data_uri(p): return 'data:image/png;base64,'+base64.b64encode((ROOT/p).read_bytes()).decode()

assets = read('04_预览与验收/components-manifest.json')['assets'] + read('04_预览与验收/ship-manifest.json')['assets']
harbor = [
 ('bg_home_harbor', '首页港口远景与水面', False, '左右边缘可裁；地平线约在画面上方三分之一。标题、船、吊机与按钮独立。'),
 ('bg_gameplay_harbor', '局内港口与低对比甲板背景', False, '中心区域留给实际船与箱堆；竖屏居中 cover，允许裁切左右各 10%，边缘灯柱不承载信息。短屏优先缩装饰，不裁核心 UI。'),
 ('spr_crane', '首页独立吊机装饰', True, '可移动或隐藏的位图装饰。透明区域不承接输入；不同于严格格点 UI，本图保留生成插画边缘。'),
 ('spr_dock_foreground', '首页码头前景', True, '底部有意出血，可被画面底边裁切；上缘灯柱/系缆柱属于装饰。'),
 ('app_icon_master', '应用图标母版', False, '1254 方形母版，无动态文本；未导出或认证任何发布平台规格。')
]
for id, purpose, alpha, note in harbor:
    assets.append(dict(id=id, file=f'01_可交付/Sprites/Harbor/{id}.png', source=f'02_可编辑源文件/Harbor/PNG母版/{id}.png',
        category='Harbor', purpose=purpose, origin='image_gen', transparent=alpha, pivot=[.5,.5], border=[0,0,0,0], recommendedFilter='Point', notes=note))
for a in assets:
    p = ROOT / a['file']
    with Image.open(p) as im:
        im.load()
        a.update(width=im.width, height=im.height, colorMode=im.mode)
        if im.mode == 'RGBA':
            al=im.getchannel('A'); hist=al.histogram()
            a['alpha']={'min':min(i for i,n in enumerate(hist) if n), 'max':max(i for i,n in enumerate(hist) if n),
                'transparentPixels':hist[0], 'opaquePixels':hist[255], 'partialAlphaPixels':sum(hist[1:255]),
                'nonzeroBoundsTopLeftExclusive':list(al.getbbox()) if al.getbbox() else None}
        else: a['alpha']=None
    assert (ROOT/a['source']).exists(), a['source']
    a.update(bytes=p.stat().st_size, sha256=digest(p), sourceSha256=digest(ROOT/a['source']))
    a['unityRecommendation']={'textureType':'Sprite (2D and UI)', 'spriteMode':'Single', 'meshType':'Full Rect',
         'filterMode':'Point', 'mipmaps':False, 'compression':'None for first visual review', 'pixelsPerUnit':100,
         'maxSize':2048 if max(a['width'],a['height'])>1024 else 1024, 'generateMetaFiles':False}
audiofont=read('04_预览与验收/audio-font-manifest.json')
manifest={'schemaVersion':1,'title':'港口装箱 · 像素夜港轻扁平资产包','version':'1.0','date':'2026-10-16',
 'scope':'Standalone art delivery only; no Unity project integration',
 'counts':{'png':len(assets),'svgComponents':67,'layeredSceneSvg':1,'wav':len(audiofont['audio']),'ttf':1},
 'borderOrder':['left','bottom','right','top'],'borderUnits':'exported PNG pixels','pivotUnits':'normalized bottom-left',
 'assets':assets,'audio':audiofont['audio'],'fonts':audiofont['fonts']}
dump('asset-manifest.json',manifest)
write('asset-data.js','window.PORTCARGO_ASSETS = '+json.dumps(manifest,ensure_ascii=False)+';\n')

# Editable component layout: raster layers stay original, vector boat stays editable in its own source.
layers=[('water_and_sky','bg_home_harbor',0,0,1536,1024),('crane','spr_crane',48,170,450,450),
 ('empty_ship','spr_ship_empty',560,390,850,425),('foreground_dock','spr_dock_foreground',0,710,1536,639)]
svg=['<svg xmlns="http://www.w3.org/2000/svg" xmlns:xlink="http://www.w3.org/1999/xlink" width="1536" height="1024" viewBox="0 0 1536 1024">',
 '<title>首页港口分层组合：每个 group 可独立移动；插画内部仍为位图</title>']
for name,id,x,y,w,h in layers:
    svg.append(f'<g id="{name}" transform="translate({x} {y})"><image width="{w}" height="{h}" preserveAspectRatio="none" xlink:href="{data_uri("01_可交付/Sprites/Harbor/"+id+".png")}"/></g>')
svg.append('</svg>')
write('02_可编辑源文件/Harbor/home_harbor_layers.svg','\n'.join(svg))
dump('02_可编辑源文件/Harbor/home-layout.json',{'canvas':[1536,1024],'coordinateOrigin':'top-left',
 'notes':'Art layout only. Grouped raster components, not internal vector layers. Runtime labels and actions are separate.',
 'layers':[dict(name=n,asset=id,x=x,y=y,width=w,height=h) for n,id,x,y,w,h in layers]})

