tiles=''.join(f'<div class="tile" style="background-image:url(../01_可交付/Sprites/UI/level_tile_{"completed" if i<6 else "current" if i==6 else "locked"}.png)"><b>{i:02d}</b><small>{"已完成" if i<6 else "进行中" if i==6 else "未解锁"}</small></div>' for i in range(1,9))
levels=f'''<div class="phone dialog"><div class="gamehead"><span>航线进度</span>{img('Icons','icon_close')}</div><div class="panel"><div class="eyebrow">CAMPAIGN</div><h2>选择关卡</h2><p>已完成 5 / 50 关</p><div class="tiles">{tiles}</div><div class="pagination">{img('Icons','icon_previous')}<span>1 / 7</span>{img('Icons','icon_next')}</div>{button('返回首页',False)}</div><div class="captionnote">每页 8 项 · 末页仅 49 / 50</div></div>'''
settings=f'''<div class="phone dialog"><div class="gamehead"><span>夜港设置</span>{img('Icons','icon_close')}</div><div class="panel"><div class="eyebrow">PREFERENCES</div><h2>按你的节奏</h2><p>轻一点，也听得清楚。</p>'''
for ic,name,state in [('sound','音效',True),('music','音乐',True),('reduced_motion','减少动效',False)]:
    settings+=f'<div class="settingrow">{img("Icons","icon_"+ic)}<span>{name}</span><button class="toggle {"on" if state else "off"}" aria-pressed="{str(state).lower()}"><i></i><b>{"开" if state else "关"}</b></button></div>'
